def threeSum(nums):
    # 核心思路：先排序，固定第一个数后用双指针找另外两个数
    # 跳过重复的固定值和重复的指针值，避免结果出现相同三元组
    # 三数之和小于 0 左移左指针，大于 0 右移右指针
    # 时间复杂度 O(n^2)，空间复杂度 O(1)（不计结果）
    nums.sort()
    n = len(nums)
    res = []
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        l, r = i + 1, n - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s < 0:
                l += 1
            elif s > 0:
                r -= 1
            else:
                res.append([nums[i], nums[l], nums[r]])
                while l < r and nums[l] == nums[l + 1]:
                    l += 1
                while l < r and nums[r] == nums[r - 1]:
                    r -= 1
                l += 1
                r -= 1
    return res

