def findAnagrams(s, p):
    # 核心思路：固定长度的滑动窗口配合 26 位频次数组
    # need 统计 p 的字符频次，win 统计当前窗口的频次
    # 窗口长度达到 m 后每步右进一左出一，频次相等即命中
    # 时间复杂度 O(n)，空间复杂度 O(1)
    if len(s) < len(p):
        return []
    need = [0] * 26
    win = [0] * 26
    for c in p:
        need[ord(c) - 97] += 1
    m = len(p)
    res = []
    for i, c in enumerate(s):
        win[ord(c) - 97] += 1
        if i >= m:
            win[ord(s[i - m]) - 97] -= 1
        if i >= m - 1 and win == need:
            res.append(i - m + 1)
    return res

