        if (i >= m - 1 && win == need) res.push_back(i - m + 1);
    }
    if (res.empty()) {
        cout << '\n';
        return 0;
    }
    for (size_t i = 0; i < res.size(); i++) {
        if (i) cout << ' ';
        cout << res[i];
    }
    cout << '\n';
    return 0;
}

